 if(!isCurrent()||dialogVersion!==modalGeneration)return;
 const stillOpen=modal(scope==='all'?'Excluir todos os lançamentos':'Excluir lançamentos selecionados',`<div class="info warning"><strong>Atenção: esta ação remove ${preview.count} lançamento(s) da empresa ${esc(preview.company_name)}.</strong><p>Os arquivos físicos seguem a política de retenção, mas os registros deixam de aparecer no sistema.</p></div>${preview.blocked_running?'<div class="info warning">Há processamento em andamento. Aguarde antes de confirmar.</div>':''}<form id="bulk-delete-form" class="form-stack"><label>Senha de exclusão<input id="delete-password" type="password" autocomplete="off" minlength="4" maxlength="4" pattern="[A-Za-z0-9]{4}" required></label><p>Configure ou altere essa senha em Meus dados.</p><label>Digite a quantidade exata: ${preview.count}<input id="confirm-count" type="number" min="1" required></label><button class="danger" ${preview.blocked_running?'disabled':''}>Excluir ${preview.count} lançamento(s)</button></form>`);
