async function renderQueue(){const isCurrent=beginViewRead('renderQueue');const q=await api('/queue?company='+cid);if(!isCurrent())return;const names={pending:'Aguardando',running:'Processando',manual:'Ação manual',retrying:'Nova tentativa',failed:'Falhas',completed:'Finalizados',cancelled:'Cancelados'};$('#main').innerHTML=heading('Fila de processamento','Cada documento avança de forma independente.','<button id="queue-add" class="primary">+ Adicionar chaves</button>')+`<div class="stats">${['pending','running','manual','failed'].map(s=>`<div class="stat"><label>${names[s]}</label><strong>${q.counts[s]||0}</strong></div>`).join('')}</div><div class="panel panel-pad"><h3>${q.paused?'Fila pausada':'Fila habilitada'}</h3><p class="muted">Atualização a cada 10 segundos. Pausar impede novas etapas; uma etapa em andamento pode terminar.</p><div class="actions"><button data-queue="pause">Pausar</button><button data-queue="resume" class="primary">Retomar</button><button data-queue="cancel">Cancelar pendentes</button></div><div class="info">Sem integração autorizada, a consulta fica em “Ação manual”. Anexe o arquivo obtido e retome a etapa. Não há estimativa fictícia para 100.000 documentos.</div><h3>Todos os estados</h3><div class="detail-grid">${Object.entries(names).map(([k,v])=>`<div><small>${v}</small><strong>${q.counts[k]||0}</strong></div>`).join('')}</div></div>`;$('#queue-add').onclick=addBatch;$$('[data-queue]').forEach(b=>b.onclick=()=>action(async()=>{if(b.dataset.queue==='cancel'&&!confirm('Cancelar os trabalhos ainda sem XML desta empresa?'))return;await api('/queue',{method:'POST',body:{company:cid,action:b.dataset.queue}});await renderQueue()}))}
