async function mountFiscalUpdates(isCurrent){
 const host=$('#updates-fiscal');if(!host)return;
 const alive=()=>isCurrent()&&host.isConnected&&page==='integrations';
 let status,busy=false,applying=false,applyStarted=0,previousVersion='';
 host.innerHTML='<h2>Atualizações do fiscal</h2><p role="status">Consultando configuração…</p>';
 try{status=await api('/updates')}catch(error){if(alive())host.textContent='Atualizações indisponíveis: '+error.message;return}
 if(!alive())return;
 host.innerHTML=`<h2>Atualizações do fiscal</h2><p>Baixa novas versões em segundo plano. Você aplica quando puder reiniciar o site; o download não interrompe o trabalho.</p><form id="updates-settings" class="form-stack"><label>Fonte das atualizações<input name="source" value="${esc(status.source||'')}" placeholder="HTTPS do latest.json, servidor localhost ou caminho compartilhado" autocomplete="off"></label><label><input name="automatic" type="checkbox" ${status.automatic?'checked':''}> Verificar e baixar automaticamente</label><button>Salvar configuração</button></form><p id="updates-guide"></p><p id="updates-state" role="status" aria-live="polite"></p><div class="actions"><button id="updates-check">Verificar agora</button><button id="updates-apply" class="primary">Aplicar e reiniciar site</button></div>`;
 const form=host.querySelector('#updates-settings'),message=host.querySelector('#updates-state'),guide=host.querySelector('#updates-guide'),check=host.querySelector('#updates-check'),apply=host.querySelector('#updates-apply');
 const names={idle:'Aguardando verificação',available:'Nova versão disponível',busy:'Operação em andamento',not_configured:'Fonte não configurada',checking:'Verificando versões',downloading:'Baixando atualização',ready:'Atualização pronta',installing:'Instalando',updated:'Atualização concluída',error:'Falha na atualização',current:'Versão atual'};
 function paint(){
  if(!alive())return;
  const running=['checking','downloading','installing'].includes(status.state);
  const blocked=!status.supported||status.manageable===false||busy||applying||running;
  form.querySelectorAll('input,button').forEach(control=>control.disabled=blocked);
  check.disabled=blocked||!status.configured;apply.disabled=blocked||status.state!=='ready';
  guide.textContent=!status.supported?'Este recurso requer a instalação local do site fiscal.':status.manageable===false?'Somente o administrador da instalação pode configurar ou aplicar atualizações.':!status.configured?'Para receber versões, publique o latest.json e os pacotes em uma fonte HTTPS, servidor local (127.0.0.1/localhost) ou pasta compartilhada e informe essa fonte uma vez. Sem fonte configurada, nenhuma versão será buscada.':'A fonte configurada será consultada; aplicar uma versão reinicia o site.';
  message.textContent=(names[status.state]||status.state||'Situação indisponível')+' · versão '+(status.current_version||'não informada')+(status.available_version?' · disponível '+status.available_version:'')+(status.message?' · '+status.message:'')+(status.checked_at?' · verificado '+date(status.checked_at):'')+(status.prepared_at?' · preparado '+date(status.prepared_at):'');
 }
 async function refresh(){const next=await api('/updates');if(alive()){status=next;paint()}}
 function schedule(){if(!alive())return;stopUpdatesPoll();updatesPollTimer=setTimeout(tick,3000)}
 async function tick(){
  updatesPollTimer=null;if(!alive())return;
  if(busy&&!applying){schedule();return}
  try{
   if(applying){
    const health=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(6000)});
    if(health.ok){const response=await fetch('/api/updates',{cache:'no-store',signal:AbortSignal.timeout(6000)});if(response.ok){const next=await response.json();if(!alive())return;status=next;
     if(next.state==='error'){applying=false;busy=false;paint()}
     else if(next.state==='updated'||(next.current_version&&next.current_version!==previousVersion)){stopUpdatesPoll();location.reload();return}
    }}
    if(applying&&Date.now()-applyStarted>600000){applying=false;busy=false;paint();message.textContent='O site ainda não confirmou o fim da atualização. Reabra esta página para consultar o estado; não repita a instalação.'}
   }else await refresh();
  }catch(error){if(alive()&&!applying)message.textContent='Não foi possível consultar a atualização. Nova tentativa em instantes.'}
  schedule();
 }
 async function mutate(path,body){if(busy||applying||!status.supported||status.manageable===false)return;busy=true;paint();try{await api(path,{method:'POST',body});if(alive())await refresh()}catch(error){if(alive())message.textContent=error.message}finally{busy=false;if(alive()){const text=message.textContent;paint();message.textContent=text}schedule()}}
 form.onsubmit=event=>{event.preventDefault();return mutate('/updates/settings',{source:form.elements.source.value.trim(),automatic:form.elements.automatic.checked})};
 check.onclick=()=>mutate('/updates/check',{});
 apply.onclick=async()=>{
  if(busy||applying||!status.supported||status.manageable===false||status.state!=='ready')return;
  applying=true;busy=true;applyStarted=Date.now();previousVersion=status.current_version;paint();message.textContent='Aplicando atualização. A cópia do pacote pode levar alguns minutos; aguardando o site reiniciar…';stopUpdatesPoll();
  try{const response=await fetch('/api/updates/apply',{method:'POST',signal:AbortSignal.timeout(8000),headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:'{}'});
   if(!response.ok){const result=await response.json().catch(()=>({}));if(alive()){applying=false;busy=false;paint();message.textContent=result.error||'Não foi possível iniciar a atualização.'}}
  }catch(error){/* The local server may disconnect while restarting. Poll before concluding. */}
  schedule();
 };
 paint();schedule();
}
window.addEventListener('pagehide',stopUpdatesPoll);

