 $('#company-form').insertAdjacentHTML('afterbegin','<label>Organização<select id="new-registration-org">'+options+'</select></label><label>Cliente (opcional)<select id="new-registration-client"></select></label><p class="muted">Escolha a organização. Sem cliente selecionado, será criado ou usado o cliente padrão da organização.</p>');
