 if(clients.some(c=>c.id===orgScope?.client&&c.provider_id===companyOrg.value))companyClient.value=orgScope.client;
 $('#main').insertAdjacentHTML('afterbegin','<section class="panel panel-pad"><h2>Cadastros</h2><p>Prestadora → Cliente → CNPJ/CPF. Abra apenas a opção que deseja cadastrar.</p>'+
 managed.map(p=>'<p><strong>'+esc(p.name)+'</strong> · CNPJs próprios: '+esc(p.documents.join(', ')||'nenhum cadastrado')+'</p>').join('')+
 '<div class="grid2"><form id="provider-form" class="form-stack"><label>Nome da prestadora<input name="name" required minlength="2" maxlength="200"></label><button>Cadastrar prestadora</button></form>'+
 '<form id="provider-tax-form" class="form-stack"><label>Prestadora<select name="provider" required>'+options+'</select></label><label>CNPJ próprio da prestadora<input name="document" required></label><button '+(!managed.length?'disabled':'')+'>Adicionar CNPJ próprio</button></form>'+
 '<form id="client-form" class="form-stack"><label>Prestadora<select name="provider" required>'+options+'</select></label><label>Nome do cliente / grupo<input name="name" required minlength="2" maxlength="200"></label><button '+(!managed.length?'disabled':'')+'>Cadastrar cliente</button></form>'+
 '<form id="registration-link-form" class="form-stack"><label>Cliente<select name="client" required><option value="">Selecione o cliente</option>'+clientOptions+'</select></label><label>CNPJ/CPF existente<select name="company">'+companies.filter(c=>!c.client_id&&c.role==='admin').map(c=>'<option value="'+c.id+'">'+esc(c.name+' · '+c.document)+'</option>').join('')+'</select></label><button '+(!clients.length?'disabled':'')+'>Vincular cadastro existente</button></form></div></section>');
 const organizationGrid=$('#provider-form').parentElement;
 organizationGrid.className='registration-actions';
 for(const [id,title,description] of [
 ['provider-form','Nova prestadora','Cadastre a empresa que atende os clientes.'],
 ['client-form','Novo cliente','Escolha a prestadora e informe o nome do cliente.'],
 ['provider-tax-form','CNPJ da prestadora','Adicione um CNPJ próprio da empresa prestadora.'],
 ['registration-link-form','Organizar cadastro existente','Vincule um CNPJ/CPF já cadastrado ao cliente correto.']
 ]){
 const form=$('#'+id),box=document.createElement('details');
 box.className='registration-action';
 box.innerHTML='<summary>'+esc(title)+'</summary><p>'+esc(description)+'</p>';
 organizationGrid.append(box);box.append(form);
 box.addEventListener('toggle',()=>{if(box.open)organizationGrid.querySelectorAll('details').forEach(other=>{if(other!==box)other.open=false})});
 }
 function submit(id,build){$(id).onsubmit=e=>{e.preventDefault();action(async()=>{const d=new FormData(e.target);const [path,body]=build(d);await api(path,{method:'POST',body});await enter();toast('Cadastro salvo.');})}}
 submit('#provider-form',d=>['/teams',{name:d.get('name')}]);
