async function mountProfileEditor(){
 const p=await api('/profile');let avatar=p.avatar;
 $('#main').insertAdjacentHTML('afterbegin',`<section class="panel panel-pad"><h2>Meu perfil</h2><form id="profile-form" class="form-stack"><label>Nome de exibição<input name="name" maxlength="80" value="${esc(p.name)}"></label><img id="avatar-preview" class="avatar-preview ${avatar?'':'hidden'}" alt="Prévia do avatar" src="${esc(avatar)}"><label>Foto do avatar (até 1 MB)<input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="actions"><button type="button" id="remove-avatar">Remover foto</button><button class="primary">Salvar perfil</button></div></form></section>`);
 $('#avatar-file').onchange=()=>action(async()=>{const f=$('#avatar-file').files[0];if(!f)return;if(f.size>1000000||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Use PNG, JPEG ou WebP de até 1 MB.');avatar=await new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>resolve(rd.result);rd.onerror=reject;rd.readAsDataURL(f)});$('#avatar-preview').src=avatar;$('#avatar-preview').classList.remove('hidden')});
 $('#remove-avatar').onclick=()=>{avatar='';$('#avatar-file').value='';$('#avatar-preview').classList.add('hidden')};
 $('#profile-form').onsubmit=e=>{e.preventDefault();action(async()=>{await api('/profile',{method:'POST',body:{name:e.target.elements.name.value,avatar}});await mountProfile();toast('Perfil salvo.')})};
}

let backdropUrl='';
function showBackdrop(url,kind){
 let el=$('#site-backdrop');if(!el){el=document.createElement('div');el.id='site-backdrop';$('.workspace').prepend(el)}
 el.replaceChildren();if(!url)return;
 const media=document.createElement(kind==='video'?'video':'img');media.src=url;
 if(kind==='video'){media.muted=true;media.loop=true;media.playsInline=true;media.autoplay=!matchMedia('(prefers-reduced-motion: reduce)').matches;media.setAttribute('aria-label','Vídeo de fundo');const toggle=document.createElement('button');toggle.className='backdrop-toggle';toggle.textContent='Reproduzir / pausar fundo';toggle.onclick=()=>media.paused?media.play().catch(()=>toast('Formato de vídeo não suportado pelo navegador.')):media.pause();el.append(toggle)}else media.alt='';
 media.onerror=()=>toast('Não foi possível exibir esse fundo. Tente outro arquivo.');el.append(media);
}
async function loadBackdrop(pid,ticket){
 if(!pid){showBackdrop('','');backdropUrl='';return}
 const url='/api/appearance-media/'+encodeURIComponent(pid);
 if(backdropUrl===url)return;
 const res=await fetch(url+'?info=1',{signal:AbortSignal.timeout(4000)});if(ticket!==appearanceRequest)return;
 if(!res.ok){showBackdrop('','');backdropUrl='';if(res.status===404)return;throw Object.assign(Error('Falha ao carregar fundo.'),{status:res.status})}
 const data=await res.json();if(ticket!==appearanceRequest)return;backdropUrl=url;showBackdrop(url,data.kind);
}
async function mountBackdropEditor(pid,editable,a){
 $('#main').insertAdjacentHTML('beforeend',`<section class="panel panel-pad"><h2>Foto ou vídeo de fundo</h2><p>Imagem ou vídeo de até 12 MB. Vídeos ficam sem som e em repetição.</p><input id="backdrop-file" aria-label="Arquivo de fundo" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm" ${editable?'':'disabled'}><div class="actions"><button id="save-backdrop" ${editable?'':'disabled'}>Salvar fundo</button><button id="remove-backdrop" ${editable?'':'disabled'}>Remover fundo</button></div><p>O arquivo só é salvo ao clicar em Salvar fundo.</p><div id="backdrop-position" class="form-stack"><h3>Enquadramento do fundo</h3><p>Ajuste olhando a prévia no fundo. Salve o enquadramento abaixo.</p>${[['bg_zoom','Zoom',100,250,a.bg_zoom??100],['bg_x','Posição horizontal',0,100,a.bg_x??50],['bg_y','Posição vertical',0,100,a.bg_y??50],['bg_blur','Desfoque (0 = sem efeito)',0,20,a.bg_blur??0],['bg_opacity','Visibilidade do fundo',10,100,a.bg_opacity??100]].map(([name,label,min,max,value])=>`<label>${label} <output id="${name}-value">${value}${name==='bg_blur'?' px':'%'}</output><input form="appearance-form" name="${name}" type="range" min="${min}" max="${max}" step="1" value="${value}" ${editable?'':'disabled'}></label>`).join('')}<div class="actions"><button id="center-backdrop" type="button" ${editable?'':'disabled'}>Centralizar e redefinir zoom</button><button form="appearance-form" type="submit" class="primary" ${editable?'':'disabled'}>Salvar ajustes do fundo</button></div></div></section>`);
 const position=()=>Object.fromEntries(['bg_zoom','bg_x','bg_y','bg_blur','bg_opacity'].map(k=>[k,Number(document.querySelector('[name='+k+']').value)]));
 const refresh=()=>{const v=position();applyBackdropPosition(v);for(const [k,n] of Object.entries(v))document.getElementById(k+'-value').textContent=n+(k==='bg_blur'?' px':'%')};
 $('#backdrop-position').oninput=refresh;
 $('#center-backdrop').onclick=()=>{for(const [k,v] of Object.entries({bg_zoom:100,bg_x:50,bg_y:50}))document.querySelector('[name='+k+']').value=v;refresh()};
 disposeBackdropPreview();
 $('#backdrop-file').onchange=()=>action(async()=>{const f=$('#backdrop-file').files[0];if(!f)return;if(f.size>12*1024*1024)throw Error('Limite de 12 MB.');disposeBackdropPreview();backdropPreview=URL.createObjectURL(f);showBackdrop(backdropPreview,f.type.startsWith('video/')?'video':'image');backdropUrl=''});
 $('#save-backdrop').onclick=()=>action(async()=>{const f=$('#backdrop-file').files[0];if(!f)throw Error('Escolha um arquivo.');const body=new FormData();body.append('file',f);await api('/appearance-media/'+pid,{method:'POST',body});disposeBackdropPreview();backdropUrl='';await loadBackdrop(pid,appearanceRequest);toast('Fundo salvo.')});
 $('#remove-backdrop').onclick=()=>action(async()=>{await api('/appearance-media/'+pid,{method:'DELETE'});disposeBackdropPreview();$('#backdrop-file').value='';showBackdrop('','');backdropUrl='';toast('Fundo removido.')});
}

function syncTheme(){const choice=document.documentElement.dataset.themeChoice;document.documentElement.dataset.theme=(choice==='dark'||(choice==='system'&&matchMedia('(prefers-color-scheme: dark)').matches))?'dark':'light';updateContrast()}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',syncTheme);

function colorLuminance(hex){const rgb=hex.replace('#','').match(/../g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]}
function contrastRatio(a,b){const x=colorLuminance(a),y=colorLuminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function updateContrast(){
 const root=document.documentElement,dark=root.dataset.theme==='dark';
 const color=root.style.getPropertyValue('--wine')||'#881b38';
 if(!/^#[0-9a-f]{6}$/i.test(color))return;
 const foreground=contrastRatio(color,'#ffffff')>=contrastRatio(color,'#000000')?'#ffffff':'#000000';
 root.style.setProperty('--on-accent',foreground);
 const surfaces=dark?['#111722','#1b2433','#253044']:['#ffffff','#f5f7fa'];
 root.style.setProperty('--accent-text',surfaces.every(bg=>contrastRatio(color,bg)>=4.5)?color:(dark?'#c4ddff':'#71213d'));
}

function applyBackdropPosition(a){
 const z=a.bg_zoom??100,x=a.bg_x??50,y=a.bg_y??50,style=document.documentElement.style;
 style.setProperty('--backdrop-blur',(a.bg_blur??0)+'px');
 style.setProperty('--backdrop-opacity',(a.bg_opacity??100)/100);
 style.setProperty('--backdrop-size',z+'%');
 style.setProperty('--backdrop-left',((100-z)*x/100)+'%');
 style.setProperty('--backdrop-top',((100-z)*y/100)+'%');
 style.setProperty('--backdrop-position',x+'% '+y+'%');
}

let backdropPreview='';
function disposeBackdropPreview(){if(backdropPreview){URL.revokeObjectURL(backdropPreview);backdropPreview='';showBackdrop('','');backdropUrl=''}}
let shellRequest=0;
async function refreshShell(){
 const ticket=++shellRequest;
 const results=await Promise.allSettled([loadAppearance(),mountProfile()]);
 if(ticket!==shellRequest)return false;
 const auth=results.find(r=>r.status==='rejected'&&r.reason?.status===401);
 if(auth){$('#shell').classList.add('hidden');$('#auth').classList.remove('hidden');throw auth.reason}
 const failures=[];
 if(results[0].status==='rejected'){++appearanceRequest;applyAppearance(appearanceDefault);showBackdrop('','');backdropUrl='';failures.push('aparência')}
 if(results[1].status==='rejected'){paintProfile({name:'Meu perfil',avatar:''});failures.push('perfil')}
 if(failures.length)toast('Não foi possível carregar '+failures.join(' e ')+'. A página continua disponível com o visual padrão.');
 return true;
}
window.addEventListener('pagehide',disposeBackdropPreview);

let viewEpoch=0;
const viewReadTickets=new Map();
function beginViewRead(key){
 const ticket=(viewReadTickets.get(key)||0)+1;viewReadTickets.set(key,ticket);
 const context={epoch:viewEpoch,page,company:cid};
 return ()=>context.epoch===viewEpoch&&context.page===page&&context.company===cid&&viewReadTickets.get(key)===ticket;
}
